-- Classic 1.60: creature loot one-to-one with VMaNGOS 1.12 (core 13b49dc, the snapshot of the world baseline; VMaNGOS has no loot
-- change after it). For every creature that exists in both databases its loot, skinning and pickpocket tables are replaced by the
-- VMaNGOS rows: items, chances, quest flags, groups and counts. Rows of Forever-only items on those tables are kept (their drops
-- need sniffs), items the 70532 client does not have are left out (the server would skip them). Forever-only creatures are not
-- touched. Fixes the sniff import (2026_10_01_04) that set vanilla quest drops to a flat 40% (Tough Wolf Meat and Red Burlap
-- Bandana were 80%, Garrick's head 100%). Report: reports/vmangos-creature-loot.md. Safe to run again.


-- Camp Narache
