UPDATE `creature_template_difficulty` d JOIN `tmp_vmangos_loot_ids` t ON t.`Entry` = d.`Entry` AND d.`DifficultyID` = 0
SET d.`LootID` = COALESCE(t.`LootID`, d.`LootID`), d.`SkinLootID` = COALESCE(t.`SkinLootID`, d.`SkinLootID`),
    d.`PickPocketLootID` = COALESCE(t.`PickPocketLootID`, d.`PickPocketLootID`);
DROP TEMPORARY TABLE `tmp_vmangos_loot_ids`;
